  "a_sentences": [
    {
      "a_text": "Selon l'art. 335b al. 1 CO, la durée de la période d'essai ne peut pas dépasser trois mois, et elle est prolongée en cas d'empêchement de travailler pour cause de maladie ou d'accident.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "La juridiction cantonale a retenu que l'exigence de forme écrite pour supprimer la prolongation de la période d'essai ne s'applique pas lorsque l'employeur manifeste, par son comportement, qu'il ne souhaite plus prolonger celle-ci.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Le Tribunal fédéral précise qu'il n'y a pas d'abus de droit à ce que la résiliation s'oriente vers le but de la période d'essai.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Il retient que l'intimée pouvait de bonne foi considérer, après les félicitations pour la période d'essai réussie, qu'elle n'était plus en période d'essai.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Le Tribunal fédéral constate qu'aucune violation du droit d'être entendu ni du droit à la contre-preuve n'est démontrée.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Il considère que l'employeur a, par les félicitations et les paiements, exprimé qu'il ne nécessitait pas de temps supplémentaire pour évaluer l'intimée et la considérait déjà comme employée fixe.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Il retient que la félicitation pour la période d'essai réussie a clairement indiqué que l'intimée avait passé cette période et n'était plus en période d'essai.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral conclut que la décision attaquée n'est pas critiquable en l'espèce.",
      "b_propositions": ["P8"]
    }
  ]
}
